# 读路径（Cache Aside 伪代码）
def get(key, loader):
    v = redis.get(key)
    if v is not None:
        return v
    # 击穿防护：互斥锁
    if redis.set("lock:" + key, 1, NX=True, EX=3):
        try:
            v = loader()                    # 查库
            if v is None:
                return None
            redis.set(key, v, EX=3600)
            redis.del("lock:" + key)
            return v
        except Exception:
            redis.del("lock:" + key)
            raise

# 雪崩防护：过期时间加随机
redis.set(key, v, EX=3600 + random(0, 300))

const Redis = require('ioredis');
const redis = new Redis({ host: '127.0.0.1', port: 6379, password: 'secret' });
redis.on('error', (e) => console.error('redis error', e));

async function main() {
  // 基本
  await redis.set('name', 'leo');
  console.log(await redis.get('name'));

  // JSON 缓存 + 过期
  const user = { id: 1, name: 'leo' };
  await redis.set('user:1', JSON.stringify(user), 'EX', 3600);
  const cached = await redis.get('user:1');
  console.log(cached ? JSON.parse(cached) : null);

  // 原子计数
  await redis.incr('pv:today');

  // 管道批量
  const pipe = redis.pipeline();
  pipe.set('a', '1');
  pipe.set('b', '2');
  await pipe.exec();

  // 事务
  await redis.multi().set('k', 'v').incr('count').exec();

  await redis.quit();
}
main();
